const int LED = {{led_pin}};

void taskBlink(void* p) {
  pinMode(LED, OUTPUT);
  while (1) {
    digitalWrite(LED, !digitalRead(LED));
    vTaskDelay(pdMS_TO_TICKS(500));
  }
}

void taskPrint(void* p) {
  while (1) {
    Serial.println("tick");
    vTaskDelay(pdMS_TO_TICKS(1000));
  }
}

void setup() {
  Serial.begin(115200);
  xTaskCreatePinnedToCore(taskBlink, "blink", 2048, NULL, 1, NULL, 0);
  xTaskCreatePinnedToCore(taskPrint, "print", 2048, NULL, 1, NULL, 1);
}

void loop() {}
